from .sack_reflection_interface import EBrowserObjectName, get_browser_object_name


class StartHsupaL2TraceQuery(Query):
    def __init__(self, req, resp):
        super(StartHsupaL2TraceQuery, self).__init__(req, resp)
        self.slaves = []

    def fill_req_msg(self, report_name, meas_period):
        # type: (int, int) -> None
        self.req_msg.contextId = (get_context_id() << 16) | (report_name & 0xffff)
        self.req_msg.procedureId = get_procedure_id()

        self.req_msg.reportName = report_name
        self.req_msg.reportPeriod = meas_period
        # self.req_msg.reportingDuration = 0

    def _handle_response(self):
        # type: (bytearray) -> None
        status = self.resp_msg.status
        if status != 0:
            LOGGER.warning('Trace collection start error (BrowserStartGeneralReportResp with status {})'.format(status))

    def _decide_if_complete(self):
        pass


class StopHsupaL2TraceQuery(Query):
    def __init__(self, req, resp):
        super(StopHsupaL2TraceQuery, self).__init__(req, resp)

    def fill_req_msg(self, report_name, context_id, procedure_id):
        # type: (int, int, int) -> None
        self.req_msg.contextId = context_id
        self.req_msg.procedureId = procedure_id
        self.req_msg.reportName = report_name

    def _handle_response(self):
        # type: () -> None
        status = self.resp_msg.status
        if status != 0:
            LOGGER.debug('Trace collection stop error (BrowserStopGeneralReportResp with status {}) '.format(status))

    def _decide_if_complete(self):
        pass


class HsupaL2TraceStartQueryManager(BasicQueryManager):
    def __init__(self, query, connection):
        super(HsupaL2TraceStartQueryManager, self).__init__(query, connection)

        self.master_board = self.query.req_msg.header.receiver.board
        self.master_cpu = self.query.req_msg.header.receiver.cpu

        self.slave_board_cpu_list = []

    def digest(self, byte_stream):
        header_length = 16
        message_header = SMessageHeader.from_buffer_copy(change_endianness(byte_stream[:header_length]))

        sender_board = message_header.sender.board
        sender_cpu = message_header.sender.cpu

        if (message_header.id == BrowserStartGeneralReportResp.id
                and (sender_board != self.master_board or sender_cpu != self.master_cpu)):
            self.query.handle_response(byte_stream)
            self.slave_board_cpu_list.append((sender_board, sender_cpu))


class HsupaL2TraceStopQueryManager(BasicQueryManager):
    def __init__(self, query, connection):
        super(HsupaL2TraceStopQueryManager, self).__init__(query, connection)


class RuntimeParameterTraceCollector(BaseTraceCollector):
    def __init__(self, connection):
        super(RuntimeParameterTraceCollector, self).__init__(connection)

        self.master_inds = []
        self.slave_inds = []

        self.master_board = None
        self.master_cpu = None

        self.report_name = EBrowserObjectName.EBrowserObjectName_HsupaL2Trace
        self.trace_name = get_browser_object_name(self.report_name)

    def find_target_board_cpu(self, cell_id):
        service = ServiceInterface(self.connection)
        candidate_board_and_cpu_ids = service.get_board_cpu_pairs_with_given_service_or_message(self.report_name)

        target_board, target_cpu = None, None
        for board, cpu in candidate_board_and_cpu_ids:
            trial_cell_ids = CellListInterface(self.connection).get_cell_ids(board, cpu)
            if cell_id in trial_cell_ids:
                target_board, target_cpu = board, cpu
                break

        if not target_cpu:
            LOGGER.warning(
                'Could not determine board and cpu for collecting {} for cell {}'.format(self.trace_name, cell_id)
            )
            return

        self.board = target_board
        self.cpu = target_cpu
        LOGGER.info('{} will be collected from master 0x{:x}{:x}'.format(self.trace_name, self.board, self.cpu))

        hsupa_user_ids = UserListInterface(self.connection).get_hsupa_user_ids(target_board, target_cpu)
        if hsupa_user_ids:
            LOGGER.debug('Found user {}'.format(hsupa_user_ids[0]))

    def stop(self):
        # stop traces on master
        self.stop_time = datetime.now()

        if not self:
            LOGGER.debug('Stop request not sent')
            return

        LOGGER.debug('Sending stop request for master 0x{:x}{:x}'.format(self.board, self.cpu))
        self.stop_qm.send_request_and_wait_for_response(timeout=1)

        # stop traces on slaves
        for slave_board, slave_cpu in self.start_qm.slave_board_cpu_list:
            LOGGER.debug('Sending stop request for slave 0x{:x}{:x}'.format(slave_board, slave_cpu))
            self.stop_qm.query.req_msg.header.receiver.board = slave_board
            self.stop_qm.query.req_msg.header.receiver.cpu = slave_cpu
            self.stop_qm.send_request_and_wait_for_response(timeout=1)

        sleep(2)  # this is to wait for all StopResponses

    def save_traces(self, output_path, as_zip=True):
        if not self:
            LOGGER.warning('No {} collected'.format(self.trace_name))
            return

        saver = ZipSaver if as_zip else TxtSaver

        self._split_inds()

        # SAVE TXT FOR MASTER
        sw_version = MiscInterface(self.connection).get_browser_sw_version(self.master_board, self.master_cpu)
        file_name = build_trace_file_name(self.master_board, self.master_cpu, self.trace_name, self.stop_time, '_master')
        master_file_path = None
        if self.master_inds:
            master_traces = prepare_report_data_for_export_to_txt_file(self.master_inds)
            master_file_path = os.path.join(output_path, file_name)
            file_header = build_trace_file_header(len(master_traces), self.report_name, sw_version,
                                                  self.start_time, self.stop_time)

            in_memory_txt_file = build_in_memory_file(file_header, master_traces)
            saver(in_memory_txt_file, master_file_path).save()
        else:
            LOGGER.warning('No {} (master) collected'.format(self.trace_name))

        # SAVE TXT FOR SLAVE
        if self.slave_inds:
            slave_traces = prepare_report_data_for_export_to_txt_file(self.slave_inds)
            file_name = file_name.replace('_master', '_slave')
            slave_file_path = os.path.join(output_path, file_name)
            file_header = build_trace_file_header(len(slave_traces), self.report_name, sw_version,
                                                  self.start_time, self.stop_time)

            in_memory_txt_file = build_in_memory_file(file_header, slave_traces)
            saver(in_memory_txt_file, slave_file_path).save()
        else:
            LOGGER.warning('No {} (slave) collected'.format(self.trace_name))

        return master_file_path

    def _split_inds(self):
        for byte_stream in self.ind_m.all_inds:
            header_length = 16
            message_header = SMessageHeader.from_buffer_copy(change_endianness(byte_stream[:header_length]))

            # BTS side
            sender_board = message_header.sender.board
            sender_cpu = message_header.sender.cpu

            if (sender_board, sender_cpu) == (self.master_board, self.master_cpu):
                self.master_inds.append(byte_stream)
            else:
                self.slave_inds.append(byte_stream)

    def prepare_query_managers(self):
        if not self:
            return

        board, cpu = self.board, self.cpu
        report_name = self.report_name
        meas_period = self.meas_period

        start_query = StartHsupaL2TraceQuery(BrowserStartGeneralReportReq(board, cpu), BrowserStartGeneralReportResp())
        start_query.fill_req_msg(report_name, meas_period)
        self.start_qm = HsupaL2TraceStartQueryManager(start_query, self.connection)

        context_id, procedure_id = start_query.req_msg.contextId, start_query.req_msg.procedureId
        stop_query = StopHsupaL2TraceQuery(BrowserStopGeneralReportReq(board, cpu), BrowserStopGeneralReportResp())
        stop_query.fill_req_msg(report_name, context_id, procedure_id)
        self.stop_qm = HsupaL2TraceStopQueryManager(stop_query, self.connection)

        self.master_board = start_query.req_msg.header.receiver.board
        self.master_cpu = start_query.req_msg.header.receiver.cpu

        self.ind_m = BrowserGeneralReportIndSink(cookie=(BrowserGeneralReportInd.id, context_id, procedure_id))


def _collect_hsupa_l2_trace(cell_id, trace_time, output_path, trace_alias, connection):
    # type: (int, int, str, str, ...) -> None
    collector = _prepare_hsupa_l2_trace_collector(cell_id, connection)
    if collector:

        TRACE_STORE.add(collector, trace_alias)

        collector.start()
        sleep(trace_time)
        collector.stop()
        collector.save_traces(output_path)


def _prepare_hsupa_l2_trace_collector(cell_id, connection):
    # type: (int, ConnectionClient) -> RuntimeParameterTraceCollector
    meas_period = 40  # ms

    collector = RuntimeParameterTraceCollector(connection)
    collector.set_parameters(
        meas_period=meas_period
    )
    collector.find_target_board_cpu(cell_id)
    collector.prepare_query_managers()
    return collector
